class Stack:
    def __init__(self):
        self._items = []               # the end of the list is the top.

    def push(self, x):                 # O(1) amortised.
        self._items.append(x)

    def pop(self):                     # O(1).
        if not self._items:
            raise IndexError("pop from empty stack")
        return self._items.pop()

    def peek(self):                    # O(1).
        if not self._items:
            raise IndexError("peek at empty stack")
        return self._items[-1]

    def is_empty(self):                # O(1).
        return not self._items

PAIRS = {")": "(", "]": "[", "}": "{"}

def balanced(code):
    stack = Stack()
    for ch in code:
        if ch in "([{":
            stack.push(ch)
        elif ch in PAIRS:
            if stack.is_empty() or stack.pop() != PAIRS[ch]:
                return False
    return stack.is_empty()            # leftovers mean unclosed brackets.
```

